import logging
from taf.internal.execution.base import Executor

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LxcExecutor(Executor):
    """
    Executor interface for Lxc executor
    """
    _start = None

    def __init__(self, tool_executor, container, is_sudo_needed=False, **kwargs):
        """
        Create an Lxc executor.

        :param tool_executor tool_executor: tool_executor to manage Lxc executor.
        :param str container: Name of the container in which instance to be executed
        :param bool is_sudo_needed: do lxc command need sudo prefix
        """
        super(LxcExecutor, self).__init__(**kwargs)
        self._container = container
        self._container_id = ""
        self._tool_executor = tool_executor
        self._is_sudo_needed = is_sudo_needed
        self._sudo_prefix = None
        self.add_prerequisite(tool_executor)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix() if self._is_sudo_needed else ''
        self._get_container_id()

    def raw_execute(self, command, use_tty=False):
        """
        Execute a command and wait until it finishes.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        """
        command = self._prepare_command(command, use_tty)
        return self._tool_executor.raw_execute(command, use_tty=use_tty)

    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging and optionally retry to start of command.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """
        lxc_command = self._prepare_command(command, use_tty)
        return self._tool_executor.start(lxc_command, use_tty=use_tty)

    def _prepare_command(self, command, use_tty):
        return ("{sudo_prefix}lxc-attach -n {container_id} -- {command}".
                format(sudo_prefix=self._sudo_prefix,
                       container_id=self._container_id,
                       command=command.decode()).encode())

    def execute(self, command, use_tty=False):
        """
        Execute a command.

        Adds logging and optionally retry to execute of command.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: bytes
        :rtype: bytes
        """
        lxc_command = self._prepare_command(command, use_tty)
        return self._tool_executor.execute(lxc_command, use_tty=use_tty)

    def __getattr__(self, name):
        return getattr(self._tool_executor, name)

    def _get_container_id(self):
        self._container_id = self._tool_executor.execute(
            "for i in $({sudo_prefix}lxc-ls) ;"
            " do echo \"$i $({sudo_prefix}lxc-attach -n $i -- uname -n 2>/dev/null)\" ;"
            " done | grep '{container}' | awk '{{print $1;}}'".format(
                sudo_prefix=self._sudo_prefix,
                container=self._container).encode('utf-8')).strip().decode('utf-8')
        if self._container_id == "":
            raise Exception("Unable to fetch container_id with container_name "
                            "having substring '{container}'".format(container=self._container))
